var e={remoteControl:{intro:{t:0,b:{t:2,i:[{t:3}],s:`向打印机上的 FilaMind 屏幕发送命令。`}},status:{ready:{t:0,b:{t:2,i:[{t:3}],s:`命令通道已连接`}},down:{t:0,b:{t:2,i:[{t:3}],s:`正在连接命令通道…`}}},show:{title:{t:0,b:{t:2,i:[{t:3}],s:`在屏幕上显示`}},status:{t:0,b:{t:2,i:[{t:3}],s:`状态`}},control:{t:0,b:{t:2,i:[{t:3}],s:`控制`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`设置`}}},locate:{title:{t:0,b:{t:2,i:[{t:3}],s:`定位屏幕`}},hint:{t:0,b:{t:2,i:[{t:3}],s:`让屏幕闪烁，以便分辨它属于哪台打印机。`}},button:{t:0,b:{t:2,i:[{t:3}],s:`定位屏幕`}}},message:{title:{t:0,b:{t:2,i:[{t:3}],s:`发送消息`}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:`输入要在屏幕上显示的简短消息…`}},level:{t:0,b:{t:2,i:[{t:3}],s:`级别`}},info:{t:0,b:{t:2,i:[{t:3}],s:`信息`}},warn:{t:0,b:{t:2,i:[{t:3}],s:`警告`}},send:{t:0,b:{t:2,i:[{t:3}],s:`发送`}}},sent:{t:0,b:{t:2,i:[{t:3}],s:`已发送`}},help:{button:{t:0,b:{t:2,i:[{t:3}],s:`帮助`}},title:{t:0,b:{t:2,i:[{t:3}],s:`远程控制 — 指南`}},close:{t:0,b:{t:2,i:[{t:3}],s:`关闭`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`功能说明`}},body:{t:0,b:{t:2,i:[{t:3}],s:`此面板可在此处操控打印机上的 FilaMind 触摸屏：切换其标签页、向其显示简短消息，或让它闪烁，以便分辨这是哪台打印机。这些都只是显示层面的提示——它们绝不会移动打印机或更改任何设置。`}}},commands:{title:{t:0,b:{t:2,i:[{t:3}],s:`命令说明`}},body:{t:0,b:{t:2,i:[{t:3}],s:`“显示”可将屏幕跳转到其“状态”、“控制”或“设置”标签页。“定位”可让屏幕闪烁几秒。“消息”可显示一条简短提示（信息或警告）。命令会发送到此打印机上的任意 FilaMind 屏幕；在命令通道仍在连接期间，不会发送任何内容。`}}}}},requiresScreen:{t:0,b:{t:2,i:[{t:3}],s:`这些控件用于操作打印机上的 FilaMind 屏幕。请在此打印机上安装 FilaMind 3D 以使用它们。`}}}};export{e as default};